function getQuestionsMatchingNeed(pool, objectiveKey, tag, excludeIds = [], skillKey = null){
    if(!Array.isArray(pool) || pool.length === 0) return [];

    const excludedIds = new Set((excludeIds || []).map(String));
    let candidates = pool.filter(question => {
        const rawId = question?.id ?? question?.questionId;
        const stableId = getStableQuestionIdentityValue(question);

        return !excludedIds.has(String(rawId))
            && !excludedIds.has(String(stableId));
    });

    if(skillKey){
        const skillMatches = candidates.filter(question =>
            resolveRecordSkill(question) === skillKey
        );
        if(skillMatches.length > 0) return skillMatches;
        // Retry matching content without recent-history exclusions before drifting.
        if(pool.some(question => resolveRecordSkill(question) === skillKey)) return [];
    }

    const objectiveMatches = candidates.filter(question =>
        inferObjective(question) === objectiveKey
    );
    if(objectiveMatches.length > 0) return objectiveMatches;
    if(pool.some(question => inferObjective(question) === objectiveKey)) return [];

    const tagMatches = candidates.filter(question => question.tag === tag);
    if(tagMatches.length > 0) return tagMatches;
    if(pool.some(question => question.tag === tag)) return [];

    return candidates;
}

